    def shunting_yard(expression):
        output = []
        operators = []
        precedence = {'+': 1, '-': 1, '*': 2, '/': 2}
        associativity = {'+': 'L', '-': 'L', '*': 'L', '/': 'L'}

        i = 0
        while i < len(expression):
            token = expression[i]

            if token.isdigit() or (token == '.' or (i > 0 and expression[i-1].isdigit() and token == '-')):
